			djnz p_setarea_so0_0
			xor a
			ld (de), a
p_setarea_so0_0_e:
			ld de, (p_setarea_a0_1)
			ld hl, var_setarea_bx_topleft_x
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_2)
			ld hl, var_setarea_bx_topleft_y
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_3)
			ld hl, var_setarea_bx_size_x
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_4)
			ld hl, var_setarea_bx_size_y
			ld bc, 2
			ldir
			ld de, (p_setarea_a0_5)
			ld hl, var_setarea_bx_area
			ld bc, 4
			ldir
			ld sp, (p_setarea_rs)
			jp ntc_xn
p_twice2_c:		; call twice2 (normal)
			pop hl			; a.x
			ld de, var_twice2_a_x
			ld bc, 2
			ldir
			pop hl			; a.y
			ld de, var_twice2_a_y
			ld bc, 2
			ldir
			ld hl, 0
			ld (var_twice2_twice2), hl
			ld (p_twice2_rs), sp
			ld sp, p_twice2
			jp ntc_xn
p_twice2_r:		; end of twice2
			ld sp, (p_twice2_rs)
			jp ntc_xn
p_corner_c:		; call corner (normal)
			pop hl			; g() descriptor
			ld de, pa_corner_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_corner_corner), hl
			ld (p_corner_rs), sp
			ld sp, p_corner
			jp ntc_xn
p_corner_r:		; end of corner
			ld sp, (p_corner_rs)
			jp ntc_xn
p_sum2_c:		; call sum2 (normal)
			pop hl			; g() descriptor
			ld de, pa_sum2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_sum2_sum2), hl
			ld hl, 0
			ld (var_sum2_r), hl
			ld hl, 0
			ld (var_sum2_c), hl
			ld (p_sum2_rs), sp
			ld sp, p_sum2
			jp ntc_xn
p_sum2_r:		; end of sum2
			ld sp, (p_sum2_rs)
			jp ntc_xn
p_cols_c:		; call cols (normal)
			pop hl			; g() descriptor
			ld de, pa_cols_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_cols_cols), hl
			ld (p_cols_rs), sp
			ld sp, p_cols
			jp ntc_xn
p_cols_r:		; end of cols
			ld sp, (p_cols_rs)
			jp ntc_xn
p_clear2_c:		; call clear2 (normal)
			pop hl			; g() descriptor
			ld de, pa_clear2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_clear2_r), hl
			ld hl, 0
			ld (var_clear2_c), hl
			ld (p_clear2_rs), sp
			ld sp, p_clear2
			jp ntc_xn
p_clear2_r:		; end of clear2
			ld sp, (p_clear2_rs)
			jp ntc_xn

